import{R as s,e as a,f as t,U as n}from"./chunks/framework.ywem4qy5.js";const g=JSON.parse('{"title":"Submission screening","description":"","frontmatter":{},"headers":[],"relativePath":"forms/submission-screening.md","filePath":"forms/submission-screening.md","lastUpdated":1776309454000}'),i={name:"forms/submission-screening.md"};function r(o,e,c,d,h,l){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="submission-screening" tabindex="-1">Submission screening <a class="header-anchor" href="#submission-screening" aria-label="Permalink to &quot;Submission screening&quot;">​</a></h1><p>Submission screening is Formie’s unified layer for deciding whether a submission should be treated as legitimate before it is saved and dispatched. It runs in the submission workflow’s <strong><code>screen</code></strong> stage, immediately after field validation and before authorization, persistence, and notifications.</p><p>Screening combines <strong>captcha integrations</strong> (provider-backed challenges and token checks) with <strong>server-side spam rules</strong> so you can tune friction for real users while still blocking automated abuse.</p><h2 id="how-screening-fits-the-workflow" tabindex="-1">How screening fits the workflow <a class="header-anchor" href="#how-screening-fits-the-workflow" aria-label="Permalink to &quot;How screening fits the workflow&quot;">​</a></h2><p>For a normal submit request, Formie runs the <code>screen</code> stage in a fixed order:</p><ol><li><strong><code>screen.runCaptchaChecks</code></strong> — every captcha integration enabled for the form runs in turn. If a captcha fails validation, the submission is marked as spam with a clear reason and the captcha class is recorded for review.</li><li><strong><code>screen.runSpamChecks</code></strong> — plugin-level rules such as spam keywords and IP matching are applied against the submission content.</li></ol><p>That ordering means provider-backed checks run first, then broader text and network rules. Draft saves and non-submit actions skip this stage so editors and save-and-continue flows are not blocked by captchas or keyword lists.</p><p>For a deeper look at stages, tasks, and extension points, see <a href="/developers/submission-workflow">Submission Workflow</a>.</p><h2 id="captcha-integrations" tabindex="-1">Captcha integrations <a class="header-anchor" href="#captcha-integrations" aria-label="Permalink to &quot;Captcha integrations&quot;">​</a></h2><p>Captcha integrations cover everything from visible challenges to invisible tokens and third-party spam APIs that classify content without showing a puzzle.</p><p>Configure them under <strong>Formie → Settings → Integrations</strong>, then enable the ones you need per form. Provider-specific setup lives under <a href="/integrations/captchas/akismet">Captchas</a> in the integrations section of these docs.</p><h2 id="spam-keywords-and-related-settings" tabindex="-1">Spam keywords and related settings <a class="header-anchor" href="#spam-keywords-and-related-settings" aria-label="Permalink to &quot;Spam keywords and related settings&quot;">​</a></h2><p>Spam keywords, IP lists, and related options live under <strong>Formie → Settings → Spam</strong>. They apply across forms after captcha checks, which keeps simple keyword blocking available even when you are not using a third-party provider.</p><p>Day-to-day behaviour of those settings (saving spam, user-visible responses, notifications) is described in <a href="/forms/spam-protection">Spam Protection</a>.</p><h2 id="why-a-dedicated-screening-stage" tabindex="-1">Why a dedicated screening stage <a class="header-anchor" href="#why-a-dedicated-screening-stage" aria-label="Permalink to &quot;Why a dedicated screening stage&quot;">​</a></h2><p>Grouping captchas and spam rules in one workflow stage keeps behaviour predictable for custom code: validation errors surface in the <strong><code>validate</code></strong> stage, while spam and abuse signals are handled in <strong><code>screen</code></strong>. If you need to insert extra checks, you can register tasks before or after the built-in screening tasks without replacing the whole submission pipeline.</p>',16)])])}const u=s(i,[["render",r]]);export{g as __pageData,u as default};
